// --- Vector3 array -----------------------------------------------------------

// [[Rcpp::export]]
void draw_triangle_strip_3d_(Rcpp::NumericMatrix points, Color color) {
  int n = points.nrow();
  std::vector<Vector3> pts(n);
  for (int i = 0; i < n; i++) {
    pts[i] = {(float)points(i, 0), (float)points(i, 1), (float)points(i, 2)};
  }
  DrawTriangleStrip3D(pts.data(), pts.size(), color);
}

