// --- Matrix array function ---------------------------------------------------

static RaylibMatrix sexp_to_matrix(SEXP x) {
  Rcpp::NumericMatrix m(x);
  return RaylibMatrix {
    (float)m(0,0), (float)m(1,0), (float)m(2,0), (float)m(3,0),
    (float)m(0,1), (float)m(1,1), (float)m(2,1), (float)m(3,1),
    (float)m(0,2), (float)m(1,2), (float)m(2,2), (float)m(3,2),
    (float)m(0,3), (float)m(1,3), (float)m(2,3), (float)m(3,3)
  };
}

// [[Rcpp::export]]
void draw_mesh_instanced_(Mesh mesh, Material material, Rcpp::List transforms) {
  int n = transforms.size();
  std::vector<RaylibMatrix> mats(n);
  for (int i = 0; i < n; i++) {
    mats[i] = sexp_to_matrix(transforms[i]);
  }
  DrawMeshInstanced(mesh, material, mats.data(), n);
}

// --- raymath output-pointer functions ----------------------------------------

static Rcpp::NumericVector vec3_to_r(Vector3 v) {
  Rcpp::NumericVector r(3);
  r[0] = v.x; r[1] = v.y; r[2] = v.z;
  r.names() = Rcpp::CharacterVector::create("x", "y", "z");
  return r;
}

static Rcpp::NumericVector vec4_to_r(Vector4 v) {
  Rcpp::NumericVector r(4);
  r[0] = v.x; r[1] = v.y; r[2] = v.z; r[3] = v.w;
  r.names() = Rcpp::CharacterVector::create("x", "y", "z", "w");
  return r;
}

// [[Rcpp::export]]
Rcpp::List vector3_ortho_normalize_(Vector3 v1, Vector3 v2) {
  Vector3OrthoNormalize(&v1, &v2);
  return Rcpp::List::create(Rcpp::Named("v1") = vec3_to_r(v1), Rcpp::Named("v2") = vec3_to_r(v2));
}

// [[Rcpp::export]]
Rcpp::List quaternion_to_axis_angle_(Vector4 q) {
  Vector3 axis;
  float angle;
  QuaternionToAxisAngle(q, &axis, &angle);
  return Rcpp::List::create(Rcpp::Named("axis") = vec3_to_r(axis), Rcpp::Named("angle") = angle);
}

// [[Rcpp::export]]
Rcpp::List matrix_decompose_(RaylibMatrix mat) {
  Vector3 translation, scale;
  Vector4 rotation;
  MatrixDecompose(mat, &translation, &rotation, &scale);
  return Rcpp::List::create(
    Rcpp::Named("translation") = vec3_to_r(translation),
    Rcpp::Named("rotation") = vec4_to_r(rotation),
    Rcpp::Named("scale") = vec3_to_r(scale)
  );
}

